// Chỉ chạy trong khung quay 16:00–17:00 (Asia/Ho_Chi_Minh).
const now = new Date();
const vnMinutes = (now.getUTCHours() * 60 + now.getUTCMinutes() + 7 * 60) % (24 * 60);
const inWindow = vnMinutes >= 16 * 60 && vnMinutes <= 17 * 60 + 10;
if (!inWindow) return [];
return [{ json: { station_code: 'DONG_NAI', product_code: 'xs-mn' } }];

// Đổi HTML/JSON của nguồn thành observation. Số PHẢI là chuỗi để giữ 0 ở đầu.
const src = $input.first().json;
const station_code = 'DONG_NAI';
const product_code = 'xs-mn';
const draw_date = src.draw_date;
if (!draw_date) throw new Error('Thiếu draw_date từ nguồn.');
const prizes = {};
for (const [code, numbers] of Object.entries(src.prizes ?? {})) {
  const list = (Array.isArray(numbers) ? numbers : [numbers])
    .map((n) => String(n).trim())
    .filter((n) => /^\d{2,6}$/.test(n));
  if (list.length > 0) prizes[code] = list;
}
if (Object.keys(prizes).length === 0) return [];
const observed_at = new Date().toISOString();
const idem = `live:${station_code}:${product_code}:${draw_date}:${JSON.stringify(prizes)}`.slice(0, 120);
return [{ json: { observation: { station_code, product_code, draw_date, kind: 'live', source_id: 'src-live', prizes, observed_at }, idem } }];
